package br.com.onda;
import org.junit.Test;import static org.junit.Assert.*;
public class WebImagesTest {
 @Test public void eachThemeBuildsItsOwnInternetSearch(){String a=WebImages.search("mensagens de motivação"),b=WebImages.search("boa noite");assertNotEquals(a,b);assertTrue(a.startsWith("https://www.google.com/search?tbm=isch"));assertTrue(a.contains("mensagens+de+motiva%C3%A7%C3%A3o"));assertTrue(b.contains("boa+noite"));}
 @Test public void voicePreservesMessageTopic(){assertEquals("mensagens de motivação",WebImages.voice("procure imagens de mensagens de motivação"));assertEquals("mensagens de motivação",WebImages.voice("pesquise mensagens de motivação"));assertEquals("boa noite",WebImages.voice("Onda, busque por boa noite"));assertEquals("frases de amizade",WebImages.voice("frases de amizade"));}
 @Test public void onlySearchHostsStayInsideImageBrowser(){assertTrue(WebImages.navigation(WebImages.search("flores")));assertTrue(WebImages.navigation("https://www.google.com/imgres?imgurl=https%3A%2F%2Fexample.org%2Fa.png"));assertFalse(WebImages.navigation("https://www.google.com.evil.org/search"));assertFalse(WebImages.navigation("http://www.google.com/search"));assertFalse(WebImages.navigation("javascript:alert(1)"));}
 @Test public void sharingAllowsOnlyPublicHttpsOrInlineRasterImages(){assertEquals("https://images.example.org/a.jpg?token=a%2Bb",WebImages.image("https://images.example.org/a.jpg?token=a%2Bb"));for(String raw:new String[]{"file:///secret","content://secret","https://localhost/a.png","https://127.0.0.1/a.png","https://router.local/a.png","https://user:password@photo.example.org/a.png","http://photo.example.org/a.png"})try{WebImages.image(raw);fail(raw);}catch(IllegalArgumentException expected){}assertTrue(WebImages.inline("data:image/png;base64,iVBORw0KGgo="));assertFalse(WebImages.inline("data:image/svg+xml;base64,AAAA"));assertFalse(WebImages.inline("data:text/html;base64,AAAA"));}
}
